//------------------------------------------------------------------------------
//Callback Name: apply_cb
//------------------------------------------------------------------------------

// Helper: safely get body tag from selection
static bool getBodyTag(NXOpen::BlockStyler::SelectObject* sel, tag_t& outTag)
{
    if (sel == NULL) return false;
    std::vector<NXOpen::TaggedObject*> objects = sel->GetSelectedObjects();
    if (objects.size() == 0) return false;
    NXOpen::Body* b = dynamic_cast<NXOpen::Body*>(objects[0]);
    if (b == NULL) return false;
    outTag = b->Tag();
    return true;
}

// Helper: get body bounding box [xmin, ymin, zmin, xmax, ymax, zmax]
static bool getBodyBBox(NXOpen::BlockStyler::SelectObject* sel, double box[6])
{
    if (sel == NULL) return false;
    std::vector<NXOpen::TaggedObject*> objects = sel->GetSelectedObjects();
    if (objects.size() == 0) return false;
    NXOpen::Body* b = dynamic_cast<NXOpen::Body*>(objects[0]);
    if (b == NULL) return false;
    UF_MODL_ask_bounding_box(b->Tag(), box);
    return true;
}

// Helper: read Enumeration value using correct API (ValueAsString + GetEnumMembers)
static int readEnumIndex(NXOpen::BlockStyler::Enumeration* e, int defaultVal)
{
    if (e == NULL) return defaultVal;
    try
    {
        std::vector<NXString> members = e->GetEnumMembers();
        NXString current = e->ValueAsString();
        for (int i = 0; i < (int)members.size(); i++)
        {
            if (strcmp(members[i].GetText(), current.GetText()) == 0)
                return i;
        }
    }
    catch (...) { }
    return defaultVal;
}

int MoveandCut::apply_cb()
{
    int errorCode = 0;
    try
    {
        // 1. Validate selection
        tag_t bodyTag = NULL_TAG;
        if (!getBodyTag(selection0, bodyTag))
        {
            theUI->NXMessageBox()->Show("Error", NXOpen::NXMessageBox::DialogTypeWarning, "Select a body first");
            return 1;
        }

        // 2. Read start/end point modes
        double startPt[3] = {0, 0, 0};
        double endPt[3]   = {0, 0, 0};

        // Start point: manual point first, fall back to enum
        bool hasManualStart = false;
        try { NXOpen::Point3d pt = point0->Point(); if (pt.X != 0.0 || pt.Y != 0.0 || pt.Z != 0.0) { startPt[0]=pt.X; startPt[1]=pt.Y; startPt[2]=pt.Z; hasManualStart=true; } } catch(...) {}

        if (!hasManualStart)
        {
            int sMode = readEnumIndex(enum0, 1);
            switch (sMode)
            {
            case 0: { double b[6]; if (getBodyBBox(selection0, b)) { startPt[0]=(b[0]+b[3])/2; startPt[1]=(b[1]+b[4])/2; startPt[2]=b[5]; } } break;
            case 1: { double b[6]; if (getBodyBBox(selection0, b)) { startPt[0]=(b[0]+b[3])/2; startPt[1]=(b[1]+b[4])/2; startPt[2]=(b[2]+b[5])/2; } } break;
            case 2: { double b[6]; if (getBodyBBox(selection0, b)) { startPt[0]=(b[0]+b[3])/2; startPt[1]=(b[1]+b[4])/2; startPt[2]=b[2]; } } break;
            case 3: { try { NXOpen::Point3d pt = point0->Point(); startPt[0]=pt.X; startPt[1]=pt.Y; startPt[2]=pt.Z; } catch(...) {} } break;
            }
        }

        // End point: manual point first, fall back to enum
        bool hasManualEnd = false;
        try { NXOpen::Point3d pt = point01->Point(); if (pt.X != 0.0 || pt.Y != 0.0 || pt.Z != 0.0) { endPt[0]=pt.X; endPt[1]=pt.Y; endPt[2]=pt.Z; hasManualEnd=true; } } catch(...) {}

        if (!hasManualEnd)
        {
            int eMode = readEnumIndex(enum01, 3);
            switch (eMode)
            {
            case 0: endPt[0]=0; endPt[1]=0; endPt[2]=0; break;
            case 1: { try { NXOpen::Point3d pt = point01->Point(); endPt[0]=pt.X; endPt[1]=pt.Y; endPt[2]=pt.Z; } catch(...) {} } break;
            case 2: { double b[6]; if (getBodyBBox(selection0, b)) { endPt[0]=(b[0]+b[3])/2; endPt[1]=(b[1]+b[4])/2; endPt[2]=b[2]; } } break;
            case 3: { tag_t wcsTag, mTag; UF_CSYS_ask_wcs(&wcsTag); UF_CSYS_ask_csys_info(wcsTag, &mTag, endPt); } break;
            case 4: { double b[6]; if (getBodyBBox(selection0, b)) { endPt[0]=b[0]; endPt[1]=(b[1]+b[4])/2; endPt[2]=(b[2]+b[5])/2; } } break;
            case 5: { double b[6]; if (getBodyBBox(selection0, b)) { endPt[0]=(b[0]+b[3])/2; endPt[1]=(b[1]+b[4])/2; endPt[2]=(b[2]+b[5])/2; } } break;
            case 6: { double b[6]; if (getBodyBBox(selection0, b)) { endPt[0]=(b[0]+b[3])/2; endPt[1]=b[1]; endPt[2]=(b[2]+b[5])/2; } } break;
            }
        }

        // 3. Compute delta
        double delta[3];
        delta[0] = endPt[0] - startPt[0];
        delta[1] = endPt[1] - startPt[1];
        delta[2] = endPt[2] - startPt[2];

        // 4. Create MoveObjectBuilder
        Part* wp = theSession->Parts()->Work();
        Features::MoveObjectBuilder* builder = wp->BaseFeatures()->CreateMoveObjectBuilder(NULL);

        std::vector<NXOpen::NXObject*> objs;
        std::vector<NXOpen::TaggedObject*> selList = selection0->GetSelectedObjects();
        if (selList.size() > 0) objs.push_back(dynamic_cast<NXOpen::NXObject*>(selList[0]));
        builder->ObjectToMoveObject()->SetArray(objs);

        builder->SetMoveParents(false);

        GeometricUtilities::ModlMotion* motion = builder->TransformMotion();
        motion->SetOption(GeometricUtilities::ModlMotion::OptionsDeltaXyz);
        motion->SetDeltaX(delta[0]);
        motion->SetDeltaY(delta[1]);
        motion->SetDeltaZ(delta[2]);

        // Move mode: associative feature. Copy mode: simple copy.
        if (m_MoveMode == 0)
        {
            builder->SetAssociative(true);
            builder->SetMoveParents(false);
            builder->SetMoveObjectResult(Features::MoveObjectBuilder::MoveObjectResultOptionsMoveOriginal);
        }
        else
        {
            builder->SetMoveObjectResult(Features::MoveObjectBuilder::MoveObjectResultOptionsCopyOriginal);
        }

        // 5. Commit and update
        builder->Commit();

        NXOpen::Session::UndoMarkId mark = theSession->SetUndoMark(NXOpen::Session::MarkVisibilityVisible, "MoveandCut");
        theSession->UpdateManager()->DoUpdate(mark);
        UF_DISP_refresh();
        UF_DISP_regenerate_display();
        builder->Destroy();

        char msg[256];
        if (m_MoveMode == 0)
            sprintf(msg, "Move OK. Delta: X=%.1f Y=%.1f Z=%.1f", delta[0], delta[1], delta[2]);
        else
            sprintf(msg, "Copy OK. Delta: X=%.1f Y=%.1f Z=%.1f", delta[0], delta[1], delta[2]);
        theUI->NXMessageBox()->Show("Result", NXOpen::NXMessageBox::DialogTypeInformation, msg);
    }
    catch(exception& ex)
    {
        errorCode = 1;
        theUI->NXMessageBox()->Show("Error", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return errorCode;
}

